let residents=[];const app=document.getElementById('app');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const slug=s=>encodeURIComponent(s);const canonical=n=>residents.find(r=>r.name===n||(r.aliases||[]).some(a=>a.toLowerCase()===String(n).toLowerCase()))?.name||n;const link=n=>`<a href="#article/${slug(canonical(n))}">${esc(n)}</a>`;function searchBox(){return `<form class="search" id="search"><input id="q" placeholder="Search Wikignome" aria-label="Search encyclopedia"><button>Search</button></form>`}function wire(){let f=document.getElementById('search');if(f)f.onsubmit=e=>{e.preventDefault();location.hash='search/'+encodeURIComponent(document.getElementById('q').value)}}function home(){app.innerHTML=`<div class="welcome"><h1>Welcome to <b>Wikignome</b></h1><div>The Free Encyclopedia. Accuracy Not Guaranteed.</div><div class="subtitle">The Gnomepedia Project · ${residents.length} resident entries · Several unresolved matters</div></div>${searchBox()}<div class="columns"><section class="box"><h2>Featured article</h2><p><b>${link('Cecil Glowbones')}</b> is Gnomeville's Cake Decorating Tsar. The office's qualifications remain an active subject of discussion.</p><p>${link('Shirley Bell, Esq.')} · ${link('Mayor Toadswallow P. Thimblewick')}</p></section><section class="box"><h2>Did you know?</h2><p>…that ${link('Captain Nutters')} was elected to an office that does not exist?</p><p>…that ${link('Maude')} and ${link('Clem')} have an inconvenient connection to Woodstock?</p></section></div><h2>Browse the encyclopedia</h2><p>Explore ${residents.length} entries in our encyclopedia index. Some biographies are short; others are considerably more difficult to verify.</p><p><a class="button" href="#directory">Browse entries A–Z</a> &nbsp; <a href="#random">Surprise me</a></p><div class="notice"><b>Editorial notice:</b> Wikignome is a satirical encyclopedia of a fictional municipality. The entries are based on its working cast registry; proposed entries are labeled.</div>`;wire()}function directory(){let sorted=[...residents].sort((a,b)=>a.name.localeCompare(b.name));let letters=[...new Set(sorted.map(x=>x.name[0].toUpperCase()))];app.innerHTML=`<h1>List of Gnomeville residents, institutions and events</h1><p class="subtitle">From Wikignome, the free encyclopedia</p>${searchBox()}<p>There are <b>${residents.length}</b> entries in this directory.</p><div class="alphabet">${letters.map(l=>`<a href="#directory/letter/${encodeURIComponent(l)}">${l}</a>`).join(' ')}</div>${letters.map(l=>`<h2 id="letter-${l}">${l}</h2><ul class="directory">${sorted.filter(x=>x.name[0].toUpperCase()===l).map(x=>`<li>${link(x.name)} <span class="muted">${esc(x.species)}</span></li>`).join('')}</ul>`).join('')}`;wire()}const expandedArticles={
"Rook's Meats":`<h2>Premises</h2><p>Rook's Meats operates from a brick corner storefront with a delicatessen counter, hanging sausages, a black awning and a prominent wooden sign advertising the “biggest sausage in Gnomeville.” Its sign states “Since 1921”; the founding date is a storefront claim, not independently verified history.</p><h2>Ownership and operations</h2><p>Rook and Tiffany each own 30% of the business. Gerald, Arthur and Pickles jointly own the remaining 40%. The enterprise was intended in part to give the three former trouser tenants gainful employment outside Rook's bedroom. Gerald presents himself as an executive, Arthur is associated with cannoli and questionable quality control, and Pickles has financial and media ambitions.</p><h2>Official exterior photograph</h2><p>The approved storefront photograph depicts Gerald, in his pinstripe suit and monocle, leaning against the doorway. The image is archived locally in WikiGnome's repository and also appears in the article infobox.</p><h2>Related personnel</h2><p>${link("Rook")} · ${link("Tiffany")} · ${link("Gerald")} · ${link("Arthur")} · ${link("Pickles")}</p>`,

"Management":`<h2>Constitutional standing</h2><p>Management is the highest accepted authority in Gnomeville, exercised by ${link("Tiffany")}. Its power is neither elected nor inherited, and no constitutional clause authorizing it has been located. The municipal government, Gnomelords and other institutions generally accept Management's interventions without demanding an explanation.</p><h2>Powers and practice</h2><p>Management may appoint officials, establish offices, resolve disputes, direct municipal projects and supersede governmental decisions. The arrangement coexists with Mayor Thimblewick's municipal administration and the older territorial claims of the Gnomelords. Their legal relationships remain unresolved.</p><h2>Constitutional Interpretation No. 001</h2><p>On November 14, 2026, Management appointed ${link("Rook")} director of the ${link("Office of Constitutional Interpretation")}. The office's first ruling, <em>In re: The Authority of Management</em>, found no applicable constitutional provision but held Management's authority to be self-evident, universally accepted and not subject to further inquiry. No dissent was recorded.</p><h2>Notable exercises of authority</h2><p>Management authorized the Office of Constitutional Interpretation, allowed its director unrestricted choice of headquarters, and subsequently approved a $0 budget. Rook voluntarily selected the ${link("Constitutional Court of Last Rummage")}, a dumpster beside Rocky the Raccoon's residence. Management was also the respondent in ${link("The Naskerman Affair")}, successfully defended by Toni.</p><h2>Interpretive principle</h2><blockquote>The absence of constitutional authority shall not be construed as evidence that constitutional authority is absent.</blockquote><h2>See also</h2><p>${link("Tiffany")} · ${link("Toni")} · ${link("Gnomeville")}</p>`,

"Rocky the Raccoon":`<h2>Residence and business activities</h2><p>Rocky lives in a dumpster at the Gnomeville fairgrounds, which he also offers as an Airbnb rental. Rudy is among his known guests. The unusual overlap between private residence, short-term lodging and alleged business headquarters has attracted municipal attention.</p><h2>The Archives</h2><p>Rocky is widely suspected of operating an informal intelligence brokerage known as <em>The Archives</em> from his dumpster. The suspicion is established local lore, but the existence, scope and clientele of any intelligence operation have not been confirmed. Rocky has not provided an organizational chart.</p><h2>Cash and firearm allegations</h2><p>A cache of approximately $4,700 in cash and a handgun have been found in Rocky's dumpster. These are established details of the setting, but the provenance of the money and ownership of the firearm remain unresolved. Rocky maintains that the handgun is not his. Attorney Shirley Bell has represented Rocky in connection with his legal difficulties. No conviction is established by these reports.</p><h2>Family and financial obligations</h2><p>Rocky is the son of Angela Banditson and grandson of Francine “Grammy” Banditson-Vermicelli. Francine married Theo “Grampy” Vermicelli, making Theo's daughter Carol Rocky's step-aunt and Carol's son Rudy his step-cousin. Rocky owes Rudy exactly $14.39, an amount not apparently affected by the reported cash cache.</p><h2>October 2026 fairgrounds incident</h2><p>According to the October 5 police blotter, officers responded to a disturbance at the fairgrounds at 2:16 a.m. and found Rocky, Rook and Tony near a dumpster. The gathering was described as a neighborhood watch meeting; Tony explained, “Crime doesn't sleep.” An archived account records Rocky declining to identify himself on the grounds that he was “between addresses.” No arrests were made.</p><h2>Nearby constitutional office</h2><p>On November 14, 2026, Rook established the ${link("Constitutional Court of Last Rummage")} in the dumpster next door. Rocky has been offered the honorary title Chief Justice of the Adjacent Dumpster, but his acceptance has not been recorded.</p>`,
"Constitutional Court of Last Rummage":`<h2>Location</h2><p>When Management granted Rook unrestricted choice of headquarters, the new director voluntarily selected the dumpster next to ${link("Rocky the Raccoon")}'s fairgrounds dumpster. Rocky's existing financial entanglements, including a suspicious cash stash and $14.39 owed to Rudy, are not within the court's ordinary jurisdiction.</p><h2>Facilities</h2><ul><li>Dumpster No. 1: Rocky's private residence; visitors are requested to knock.</li><li>Dumpster No. 2: Director Rook's chambers, law library and executive washroom (a coffee can).</li><li>The alley: public hearing room with overturned milk-crate seating.</li><li>The loading dock: Court of Appeals, subject to loading schedules.</li><li>The recycling bin: constitutional archives, filed by scent.</li></ul><p>A brass plaque identifies the Office of Constitutional Interpretation and gives its office hours as <em>Whenever the Lid Is Open.</em></p><h2>Honorary judicial office</h2><p>Rocky has been offered the position of Chief Justice of the Adjacent Dumpster, with authority to disagree with Rook's rulings and retain items found in evidence. No acceptance has been recorded.</p>`,
"Office of Constitutional Interpretation":`<h2>Mandate</h2><p>The Office of Constitutional Interpretation resolves disputes about Gnomeville's many competing constitutional texts and, when resolution is impossible, explains why. Its motto is <em>Subject to Interpretation.</em></p><h2>Director</h2><p>Management appointed ${link("Rook")} as director on November 14, 2026. Rook accepted and issued Constitutional Interpretation No. 001, <em>In re: The Authority of Management</em>.</p><h2>Constitutional Interpretation No. 001</h2><p><strong>Question:</strong> By what constitutional mechanism does Management exercise supreme authority?</p><p><strong>Finding:</strong> No applicable provision has been located.</p><p><strong>Holding:</strong> Management's authority is self-evident, universally accepted and not subject to further inquiry.</p><p><strong>Dissent:</strong> None recorded. Bureaucratic Duck reportedly attempted to object but submitted a lunch order.</p><p><strong>Disposition:</strong> Case closed.</p><p>The office's guiding principle is: <em>The absence of constitutional authority shall not be construed as evidence that constitutional authority is absent.</em></p><h2>Headquarters</h2><p>The ${link("Constitutional Court of Last Rummage")} occupies the dumpster adjacent to Rocky the Raccoon's residence at the fairgrounds.</p>`,
"The Founding Gnome":`<h2>Competing identities</h2><p>Hardrock, once Nana's garden gnome and now a Gnomelord, is the oldest known gnome associated with the territory. The settlement conventionally began later with Vinnie and Paulie and their companions Guido and Mr. Pink. Whether this makes Hardrock a founder or merely an exceptionally early resident remains contested.</p><p>Other interpretations nominate Guido or Mr. Pink. A minority school argues for a wholly unidentified founder whose name has been lost. No supporting evidence has surfaced, but the theory persists.</p><h2>Commemoration</h2><p>${link("Founders\u0027 Day")} celebrates the founding without resolving the founder's identity or the date.</p>`,
"Founders' Day":`<h2>Observance</h2><p>Founders' Day is Gnomeville's official annual celebration of its origins. Its date is chosen by municipal authorities, occasionally altered without notice, and vigorously disputed by the Gnomelords. A definitive date has not been established.</p><h2>Historical controversy</h2><p>Some accounts recognize Hardrock, whose presence predates the modern settlement. Others point to Guido or Mr. Pink, who arrived alongside the flamingos Vinnie and Paulie. A minority position holds that the true ${link("The Founding Gnome")} was someone else entirely, though no evidence has been produced.</p><p>The annual commemoration proceeds regardless. The holiday's uncertain date, participants and legitimacy are considered part of its heritage.</p>`,
"Greater United Independent Gnome Treaty":`<h2>Overview</h2><p>The Greater United Independent Gnome Treaty (GUIGT) unites disparate independent gnome settlements around the world. It is a loose confederation, not a single central government. Each member retains its own laws, customs, government, territorial claims and grudges.</p><h2>Purpose and provisions</h2><p>The treaty provides mutual diplomatic recognition, cooperation and collective protection against lawnmowers, landscaping contractors and unauthorized relocation. It does not require member settlements to agree on procedural matters, including pronunciation of GUIGT.</p><h2>Institutions</h2><p>The Permanent Secretariat, Emergency Committee and Office of International Affairs are acknowledged treaty institutions. The location of their offices remains unclear.</p><h2>Diplomatic motto</h2><blockquote><strong>United in Independence. Divided on Procedure.</strong></blockquote><h2>Gnomeville's membership</h2><p>${link("Gnomeville")} participates as a self-declared micronation in Illinois. United States and Illinois recognition of Gnomeville's claimed sovereignty has not been obtained. Membership in GUIGT does not alter real-world jurisdiction.</p>`,
"Gnomeville":`<h2>Political status and geography</h2><p>Gnomeville is a self-declared micronation located in Illinois, United States. It describes itself simultaneously as a town, a city and an independent municipality. The government does not see a contradiction. It sees three opportunities to collect filing fees.</p><p>Its sovereignty is recognized by its own government and within the Greater United Independent Gnome Treaty, but not by the United States or Illinois. Gnomeville attributes this to an administrative oversight and maintains that strongly worded correspondence has been prepared, although evidence of mailing is lacking. Municipal boundaries are poorly documented; surviving maps disagree, and the town occasionally expands without a recorded zoning hearing.</p><h2>Origins and founding controversy</h2><p>The oldest known gnome associated with the territory is Hardrock, who occupied Nana's garden and later the back porch for decades before Leroy returned him to the yard. Hardrock later became a Gnomelord. Historians disagree whether his longstanding presence constituted a settlement, a territorial claim, or an extended period of sitting in a garden.</p><p>Gnomeville proper is conventionally traced to the arrival of Vinnie and Paulie, two flamingos, with their gnome companions Guido (noted for sleeping) and Mr. Pink (noted for his lantern). The original purchase date has not been established in the municipal chronology. Whether Hardrock, Guido, Mr. Pink or an entirely unknown individual deserves the title of Founding Gnome remains disputed.</p><p>The annual ${link("Founders\u0027 Day")} celebrates this history despite the absence of an agreed founding date.</p><h2>Government and constitutional order</h2><p>The ancient Gnomelords assert older territorial rights, while the municipal government, led by Mayor Toadswallow P. Thimblewick, administers modern civic affairs. Their mutual recognition remains ambiguous. Management holds ultimate authority by universal acceptance, without an identified constitutional source. No single complete copy of the constitution has been located; departments maintain competing versions. The ${link("Office of Constitutional Interpretation")} is responsible for interpreting them, when possible.</p><h2>International relations</h2><p>Gnomeville belongs to the ${link("Greater United Independent Gnome Treaty")} (GUIGT), a loose confederation of independent gnome settlements worldwide.</p><h2>Culture and institutions</h2><p>Gnomeville's civic life includes ${link("Gnomeville Museum of Strategic Pecan History")}, the Gazette, the municipal police, ${link("Rookery Commons")}, the Gnomelords' territorial politics and a flourishing tradition of paperwork. Its boundaries and institutions are capable of expansion with remarkably little warning.</p><h2>Origins outside the fiction</h2><h3>A Note Regarding the Origins of Gnomeville</h3><p>It began with a porch gnome.</p><p>As these things sometimes do, one gnome became several. Several became a community. The community developed businesses, personalities, rivalries, questionable legal representation, and eventually a municipal government.</p><p>Nobody remembers authorizing the government.</p><p>What began as a little decorating and storytelling between friends has since developed into a fictional town with its own newspapers, institutions, scandals, and increasingly elaborate administrative problems.</p><p>Gnomeville is not a real municipality. Its residents are mostly decorative, its laws are unenforceable, and its elected officials are best approached with caution.</p><p>The friendships, creativity, and laughter behind it, however, are entirely real.</p><p><strong>Life Happens Here.</strong></p>`,
"Gnomeville Museum of Strategic Pecan History":`<h2>The permanent collection: illustrated catalogue</h2><p>Explore all sixteen documented works in the museum's Diplomatic Gallery. Each WikiGnome catalogue entry includes the museum's original interpretation, an archived image, provenance notes, and clearly marked proposed critical commentary.</p><h3>Diplomatic portraits</h3><ul><li>${link("The First Summit")}</li><li>${link("The Patron and His Outstanding Balance")}</li></ul><h3>Commemorative postal art</h3><ul><li>${link("The Grand Delegation")}</li><li>${link("The Diplomatic Encounter")}</li><li>${link("The Mechanical Delegation")}</li><li>${link("The Avian Accord")}</li></ul><h3>Fine-art collection</h3><ul><li>${link("The Discovery of the Sacred Pecan")}</li><li>${link("Ceci n’est pas une noix")}</li><li>${link("The Pecan, Deconstructed")}</li><li>${link("Starry, Starry Nut")}</li><li>${link("The Persistence of Pecan")}</li><li>${link("Raven with a Pecan Earring")}</li><li>${link("The Pecan Incident, 2026")}</li><li>${link("THE PECAN™")}</li><li>${link("The Pecan Bearer")}</li><li>${link("The Great Pecan Heist")}</li></ul><h2>Visit the museum</h2><p><a href="https://gnomeville.github.io/pecan-museum/#summit">Explore the original Diplomatic Gallery at the Gnomeville Museum of Strategic Pecan History</a>.</p>`,

"The First Summit":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-001 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Diplomatic History<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/rook-raven-summit.webp" alt="The First Summit museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>The historic first meeting between Rook and Raven established the framework for future negotiations concerning institutional authority, ceremonial precedence, and the status of one pecan. The proceedings remain classified, largely because neither participant agrees on what happened.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “The catalogue's insistence on an agreed historical meaning is particularly moving given the participants' continuing disagreement.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Patron and His Outstanding Balance":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-002 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Institutional Portraiture<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/patron-outstanding-balance.png" alt="The Patron and His Outstanding Balance museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>This official portrait commemorates Raven’s patronage and Rook’s ongoing efforts to recover the institution’s outstanding balance. Raven considers the invoice a personal attack. Rook considers it an asset.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “One might call it an account receivable in portrait form. The museum has declined to confirm whether the invoice is framed elsewhere.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Grand Delegation":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-003 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Commemorative Postal Art<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/three-rooks-and-raven-summit-stamp-004.png" alt="The Grand Delegation museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>Three representations of Rook assemble for a landmark diplomatic encounter with Raven. Historians disagree on whether this constitutes one delegate or three. The pecan has declined to cast the deciding vote.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “The question is not how many Rooks attended, but how many reimbursement forms were submitted.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Diplomatic Encounter":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-004 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Commemorative Postal Art<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/raccoon-rook-and-raven-summit-stamp-002.png" alt="The Diplomatic Encounter museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>The Victorian Rook and Raven meet in a ceremony of exceptional dignity. The stamp carries a denomination of 0¢, reflecting the museum’s endowment and its optimistic approach to fiscal policy.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “An extraordinary ceremonial achievement, especially considering the complete absence of postage value.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Mechanical Delegation":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-005 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Commemorative Postal Art<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/robot-rook-and-raven-summit-stamp-003.png" alt="The Mechanical Delegation museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>The mechanical delegation arrives with impeccable documentation and no spending authority. Raven welcomes the robot but refuses to surrender custody of the pecan for routine inspection.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “Mechanical precision has seldom been so elegantly paired with an empty treasury.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Avian Accord":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-006 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Commemorative Postal Art<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/rook-and-raven-summit-stamp-001.png" alt="The Avian Accord museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>This avian commemorative issue celebrates an accord whose terms have never been successfully located. It is not valid postage. Raven maintains it should be.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “Few diplomatic achievements have been commemorated so extensively with so little evidence of their actual terms.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Discovery of the Sacred Pecan":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-007 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Dutch Golden Age<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/01-discovery-of-the-sacred-pecan.png" alt="The Discovery of the Sacred Pecan museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>The moment Raven first encountered the Original Pecan is rendered here with the gravity of a divine revelation. The precise date remains uncertain. Raven attributes the discovery to providence; other sources suggest he found it on the ground. A squirrel present at the scene has declined to comment.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “The painting transforms an uncertain encounter into the founding mythology of an entire cultural institution.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"Ceci n’est pas une noix":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-008 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Surrealism<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/02-this-is-not-a-pecan.png" alt="Ceci n’est pas une noix museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>By insisting that the painted pecan is not a nut, the artist invites visitors to distinguish between an object and its representation. Raven has objected to both classifications and demands that the painting be recognized as an official portrait of his property.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “To deny the nut is, paradoxically, to give the nut its most enduring identity.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Pecan, Deconstructed":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-009 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Cubism<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/03-the-pecan-deconstructed.png" alt="The Pecan, Deconstructed museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>The Original Pecan is fractured into competing perspectives, with Raven’s presence distributed among the planes. The work explores whether ownership can survive the collapse of a single viewpoint. Raven has requested that all viewpoints be returned to him.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “The fragmentation of the object is less alarming than the fragmentation of its chain of custody.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"Starry, Starry Nut":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-010 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Post-Impressionism<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/04-starry-starry-nut.png" alt="Starry, Starry Nut museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>Beneath a restless celestial sky, a tiny pecan assumes cosmic importance. Scholars interpret the swirling heavens as an expression of wonder, longing, and the limits of human understanding. Raven interprets them as evidence that the universe recognizes his title.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “At last, a cosmology in which the central celestial body is technically a snack.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Persistence of Pecan":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-011 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Surrealism<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/05-the-persistence-of-pecan.png" alt="The Persistence of Pecan museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>In a landscape where scale, shadow, and logic have ceased to cooperate, Rook surveys an impossible pecan with professional composure. The museum’s research department has been unable to establish whether the artifact is growing, floating, or merely refusing to comply with measurement standards.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “Time, scale and departmental measurement standards dissolve together before an uncooperative pecan.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"Raven with a Pecan Earring":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-012 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Dutch Golden Age<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/06-raven-with-a-pecan-earring.png" alt="Raven with a Pecan Earring museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>An intimate portrait elevates Raven’s pecan-shaped earring to the status of a treasured jewel. The sitter’s expression suggests quiet mystery and absolute confidence in his own importance. The earring has not been independently appraised.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “The earring is priceless, according to the sitter; the appraisal remains outstanding.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Pecan Incident, 2026":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-013 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Abstract Expressionism<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/07-the-pecan-incident.png" alt="The Pecan Incident, 2026 museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>Violent gestures of color converge upon a remarkably ordinary pecan. The composition has been interpreted as a record of conflict, possession, and institutional instability. Raven denies involvement in the incident. Rook notes that no incident report was filed.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “An incident without an incident report is the purest form of institutional abstraction.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"THE PECAN™":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-014 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Pop Art<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/08-the-pecan-trademark.png" alt="THE PECAN™ museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>Repetition transforms the Original Pecan into a commodity, a symbol, and a registered-looking brand. ORIGINAL. AUTHENTIC. EXCLUSIVE. The museum has not established whether any of these claims can be legally substantiated. Raven has already ordered merchandise.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “The trademark symbol functions as both artistic punctuation and an unresolved legal threat.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Pecan Bearer":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-015 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Art Nouveau<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/09-the-pecan-bearer.png" alt="The Pecan Bearer museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>In this ornamental celebration of nature and guardianship, Raven appears surrounded by the botanical origins of his most treasured possession. The artist’s use of flowing lines suggests harmony between bird, branch, and nut. Raven maintains that the work represents his spiritual connection to the Original Pecan. Rook notes that the pecans depicted are still attached to their branches and therefore technically belong to the tree. Raven has filed an objection.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “Here nature meets the filing cabinet: the branches retain possession, while Raven claims moral ownership.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,
"The Great Pecan Heist":`<h2>Catalogue record</h2><p><strong>Accession:</strong> GM-SPH-2026-016 (WikiGnome catalogue identifier)<br><strong>Collection:</strong> Gnomeville Museum of Strategic Pecan History, Diplomatic Gallery<br><strong>Classification:</strong> Art Deco<br><strong>Artist, medium, date:</strong> Not established in museum records.</p><figure><img src="assets/museum-artwork/10-the-great-pecan-heist.png" alt="The Great Pecan Heist museum artwork" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>WikiGnome's archived copy of the original museum gallery image. <a href="https://gnomeville.github.io/pecan-museum/#summit">View original exhibition</a>.</figcaption></figure><h2>Official curatorial interpretation</h2><p>This dramatic Art Deco composition depicts the controversial removal of the Original Pecan from its display chamber. Raven maintains that the incident constitutes grand larceny. Rook maintains that it constitutes routine debt recovery. The museum’s legal department has advised both parties that a pecan cannot reasonably secure a multimillion-dollar institutional debt. Rook has requested a second opinion.</p><h2>Critical reception</h2><p><em>Proposed catalogue commentary, not an archival quotation:</em> “The central tension is not whether the pecan was taken, but whether an outstanding balance can justify taking it.”</p><h2>Provenance and interpretation</h2><p>This work belongs to the museum's established sixteen-item Diplomatic Gallery. Its historical interpretation follows the museum's own exhibit text. A named creator, physical acquisition record and independent conservation report have not yet been documented. Interpretive disputes should not be mistaken for proven historical events.</p><h2>Related collections</h2><p>${link("Raven")} · ${link("Rook")} · ${link("The First Rook–Raven Summit")} · ${link("The Gnomeville Museum of Strategic Pecan History")}</p>`,

"The Naskerman Affair":`<h2>Overview</h2><p>On October 26, 2026, ${link("Milo Arthur Lestat Naskerman")} filed three formal grievances against ${link("Tiffany")}, known in the proceedings as <strong>Management</strong>. The dispute prompted a stairwell surveillance controversy, four published articles in the <a href="https://gnomeville.github.io/gazette/">Gnomeville Gazette</a>, and the successful defense of Management by ${link("Toni")}, who was promoted to ${link("District Attorney Toni")} that same day.</p><h2>Formal grievances</h2><ol><li><strong>Delectables shortage:</strong> Milo alleged inadequate supplies of Hartz Delectables.</li><li><strong>Unauthorized hissing:</strong> Milo objected to Momma's hissing after a disagreement involving a medication organizer and Friskies Party Mix Pumpkin treats.</li><li><strong>Complaint Department negligence:</strong> Milo alleged that the first two grievances had not been processed promptly.</li></ol><p>The documents were printed on ornate royal stationery and posted on a residential staircase. Their original printable versions are preserved in the archives:</p><ul><li><a href="assets/exhibits/naskerman-affair/Milo_Formal_Grievance_Printable.pdf">Exhibit B: Formal grievance (PDF)</a></li><li><a href="assets/exhibits/naskerman-affair/Milo_Hissing_Grievance_Printable.pdf">Exhibit C: Hissing grievance (PDF)</a></li></ul><p><a href="assets/exhibits/naskerman-affair/Milo_Complaint_Department_Grievance.pdf">Exhibit D: Complaint Department grievance (PDF)</a></p><h2>Camera 12: leaked security footage</h2><figure><img src="https://gnomeville.github.io/gazette/assets/october-2026/camera-12-evidence.png" alt="Five-frame Camera 12 stairwell surveillance collage, leaked Exhibit A" style="width:100%;height:auto"><figcaption>Exhibit A: Camera 12 surveillance collage, bearing the Public Records Office confidential watermark and leaked stamp.</figcaption></figure><p>The Public Records Office denied responsibility for the leak, despite the watermark. Bureaucratic Duck announced an investigation into himself, citing the Freedom of Information-ish Act of 1987.</p><h2>Gazette investigative series</h2><ol><li><a href="https://gnomeville.github.io/gazette/articles/naskerman-stairwell-incident.html">Cat Caught in Act of Civil Disobedience</a></li><li><a href="https://gnomeville.github.io/gazette/articles/naskerman-formal-grievances.html">Local Feline Files Three Formal Grievances Against Management</a></li><li><a href="https://gnomeville.github.io/gazette/articles/naskerman-camera-12-leak.html">Gnomeville Records Office Embroiled in Surveillance Leak Scandal</a></li><li><a href="https://gnomeville.github.io/gazette/articles/naskerman-exclusive-interview.html">“I Am the Victim Here,” Declares Milo Naskerman</a></li></ol><h2>Selected interview transcript</h2><blockquote><p><strong>Gazette:</strong> Mr. Naskerman, did you personally post these grievances?<br><strong>Milo:</strong> I don't recall.<br><strong>Gazette:</strong> We have security footage.<br><strong>Milo:</strong> Then why are you asking me?</p><p><strong>Gazette:</strong> Who is your attorney?<br><strong>Milo:</strong> Me.</p></blockquote><h2>The defense of Management: a dramatized reconstruction</h2><p><em>Historical note:</em> The following scene dramatizes Toni's defense as reported by Management on October 26, 2026. The objections and allegations are preserved from that account; the courtroom atmosphere and narrative flourishes are literary reconstruction, not a verbatim hearing transcript. The hearing's dialogue is dramatized; Paw-Paw's role as judge and his ruling for Management are established by Management's account, and his exact words are preserved in the disposition and quotations index below.</p><div class="case-reconstruction"><p>The case against Management arrived wrapped in royal stationery, purple seals, and the unmistakable confidence of a cat who had never paid a bill.</p><p>Toni examined the complaints and began with a procedural question: where was the signature of Shirley Bell, Esq.? There was none. Had Detectives Benson and Stabler investigated? No police statement, report, or interviews had been presented. An impressive quantity of paper had appeared, but the ordinary machinery of justice was conspicuously absent.</p><p>Then came the question of the complainant's standing. Milo, Toni observed, paid no rent. He provided no cuddles and no kisses. Worse, the record of his conduct toward Management included ongoing, unprovoked assaults. This was a remarkable foundation from which to accuse the household's chief provider of misconduct.</p><p>The royal complainant's demands remained uncompromising. The defense's assessment was considerably shorter.</p><blockquote><p><strong>Toni's conclusion:</strong> “He does not have a paw to stand on.”</p></blockquote><p>No verbatim courtroom exchange or gavel strike is preserved. Paw-Paw presided as judge and ruled in Management's favor following Toni's successful defense. On the same date, Toni assumed the title of District Attorney of Gnomeville, an appointment later incorporated into the town's history.</p></div><h2>Disposition</h2><p>With Paw-Paw presiding as judge, Toni successfully defended Management and Paw-Paw ruled in Management's favor. Toni was promoted to District Attorney on October 26, 2026. Paw-Paw's ruling, presented here with minor editorial corrections to spelling, grammar and punctuation, was:</p><blockquote><p>“This is a ridiculous waste of time, even for Gnomeville. I rule in favor of Management, though all parties shall be sentenced to one night in Rocky's Airbnb after Taco Tuesday. Everyone out of my courtroom! Now, where are my pants?”</p></blockquote><p>The reference to a night in Rocky's Airbnb is part of the judge's pronouncement; whether any party served this unusual sentence has not been established.</p><h2 id="naskerman-primary-sources">Primary sources &amp; quotations</h2><p>This index distinguishes <strong>verbatim quotations</strong>, <strong>Management's reported recollections</strong>, and <strong>literary dramatization</strong>. The reconstruction above is not a transcript.</p><h3 id="naskerman-paw-paw-ruling">Paw-Paw's ruling: editorially corrected quotation</h3><blockquote><p>“This is a ridiculous waste of time, even for Gnomeville. I rule in favor of Management, though all parties shall be sentenced to one night in Rocky's Airbnb after Taco Tuesday. Everyone out of my courtroom! Now, where are my pants?”</p></blockquote><p><strong>Attribution:</strong> Paw-Paw, presiding judge. <strong>Provenance:</strong> Edited for grammar and punctuation from wording supplied by Management in conversation on November 15, 2026. The original unedited wording remains in the Naskerman primary-source research index. This is Management's firsthand account, not a separately recovered court transcript.</p><h3 id="naskerman-toni-defense">Toni's defense: reported arguments</h3><p><strong>Provenance:</strong> Management's account of Toni's October 26, 2026 defense. Toni challenged the absence of Shirley Bell's signature, police involvement by Detectives Benson and Stabler, and a police statement. She noted that Milo paid no rent, provided no cuddles or kisses, and repeatedly assaulted Management. Her conclusion was reported as <strong>“He does not have a paw to stand on.”</strong> These are attributed arguments, not a certified transcript of the full defense. The dramatized scene above adds narrative presentation, not new evidence.</p><h3 id="naskerman-milo-interview">Milo's Gazette interview: verbatim excerpts</h3><p>Asked whether he posted the grievances, Milo answered <strong>“I don't recall.”</strong> Confronted with security footage, he replied <strong>“Then why are you asking me?”</strong> Asked who his attorney was, he answered <strong>“Me.”</strong> <strong>Source:</strong> <a href="https://gnomeville.github.io/gazette/articles/naskerman-exclusive-interview.html">original published Gazette interview</a>. These quotations belong to a newspaper interview, not a courtroom hearing.</p><h3 id="naskerman-original-exhibits">Original documents and reporting</h3><p><strong>Grievance PDFs:</strong> <a href="assets/exhibits/naskerman-affair/Milo_Formal_Grievance_Printable.pdf">Delectables</a>; <a href="assets/exhibits/naskerman-affair/Milo_Hissing_Grievance_Printable.pdf">hissing</a>; <a href="assets/exhibits/naskerman-affair/Milo_Complaint_Department_Grievance.pdf">Complaint Department</a>. These establish Milo's allegations, not their truth.</p><p><strong>Other sources:</strong> <a href="https://gnomeville.github.io/gazette/assets/october-2026/camera-12-evidence.png">Camera 12 collage</a>; <a href="https://gnomeville.github.io/gazette/articles/naskerman-stairwell-incident.html">stairwell story</a>; <a href="https://gnomeville.github.io/gazette/articles/naskerman-formal-grievances.html">grievances story</a>; <a href="https://gnomeville.github.io/gazette/articles/naskerman-camera-12-leak.html">leak story</a>; <a href="https://gnomeville.github.io/gazette/articles/naskerman-exclusive-interview.html">interview</a>. The collage does not establish who posted the documents.</p>`,
"Gnomeville Multiverse":`<h2>Continuity policy</h2><p>The multiverse preserves contradictory accounts as alternate continuities rather than deleting earlier stories or treating every variant as the same chronology. Its existence is approved canon; its mechanics remain open.</p><h2>The Social Security Timeline</h2><p>In this alternate continuity, ${link("Paw-Paw")} was ${link("Tiffany")}'s deceased husband and ${link("Toni")}'s father. The family retained him to cash his Social Security checks. This is a fictional alternate timeline and does not supersede Paw-Paw's principal judicial and Porch biography.</p>`,

"Paw-Paw":`<h2>Alternative continuity: the Social Security Timeline</h2><p>In an approved branch of the ${link("Gnomeville Multiverse")}, Paw-Paw was ${link("Tiffany")}'s deceased husband and ${link("Toni")}'s father. The family kept him around to cash his Social Security checks. This version is preserved as an alternative continuity, not an event in the principal Porch chronology.</p><h2>Early life and migration</h2><p>Paw-Paw was born in Scotland and lived there until after an event referred to in family lore only as <em>the War</em>. Neither the conflict nor a reliable chronology has been identified. He subsequently emigrated to the United States and eventually became a fixture of Gnomeville's Porch neighborhood. His name, Paw-Paw, has been used since his arrival in the household; his earlier personal history remains intentionally difficult to date.</p><h2>Judicial appointment</h2><p>On October 26, 2026, during the Naskerman Affair, Paw-Paw was appointed Judge of Gnomeville, joining a courtroom landscape that includes ${link("District Attorney Toni")} and the recurring legal troubles of ${link("Milo Arthur Lestat Naskerman")}. His legal qualifications are not recorded.</p><p>His judicial commentary emphasizes that not every neighborhood grievance belongs in court. Regarding trivial disputes, he has advised: “These matters belong in mediation, preferably somewhere I cannot hear them.” He has also observed: “Order will be maintained. I have no reason to believe this, but it remains the official position of the Court.”</p><h2>Other cases on the docket</h2><p><em>The following proceedings are newly developed Gnomeville fictional case histories, not recovered archival events. Their dates, where unspecified, remain undetermined.</em></p><h3>In re: The Missing Cannoli</h3><p>A cannoli vanished before its intended recipient could eat it. Arthur denied responsibility while visibly covered in powdered sugar. Paw-Paw dismissed the complaint for lack of surviving physical evidence, ruling: “The evidence has been eaten. The court cannot un-eat it.” No finding of theft was entered.</p><h3>Bureaucratic Duck v. Pickles: The Paperclip Debt</h3><p>Bureaucratic Duck petitioned for recovery of the $47 and one paperclip owed by Pickles. Paw-Paw recognized the dispute but ordered the parties to attempt mediation before returning to court, preferably somewhere he could not hear them. The debt remains outstanding; the ruling did not forgive it.</p><h3>The People v. The Unlicensed Wheelbarrow</h3><p>Arthur's wheelbarrow became the subject of a municipal complaint after an unidentified official questioned whether it required a transport permit. Paw-Paw ruled that the court could not determine whether a wheelbarrow was a vehicle without first determining whether Arthur was using it for transportation or cannoli storage. Proceedings were adjourned indefinitely. No permit requirement was established.</p><h3>In re: The Premature Lunch Recess</h3><p>Following Paw-Paw's announcement that court would recess for lunch before convening, a procedural objection was raised. The judge rejected it on the grounds that a recess could not be late if proceedings had not begun. The objection was recorded as unresolved, and lunch proceeded.</p><h2>Porch life and public appearances</h2><p>Paw-Paw is known for elaborate seasonal clothing and accessories, including Halloween, Thanksgiving, Christmas, New Year's, Valentine's Day and St. Patrick's Day ensembles. His wardrobe has featured a kilt, swim trunks and sunglasses; mouth accessories include a cigarette, candy cane, noisemaker, rose and pipe, rotated for the occasion. His displays attract photographs from passersby and neighborhood children.</p><p>He became fast friends with ${link("Tony the Porch Lizard")}. A fishing outing involving Paw-Paw and ${link("Rook")} preceded the first appearance of ${link("Gertie Marrow")} in the illustrated neighborhood sequence.</p><h2>Friends and unresolved relationships</h2><p>Paw-Paw and Gertie frequently appear together, including in Halloween photographs. Asked on Chirp whether they were married, Gertie declined to answer on grounds of municipal privacy. Their precise relationship is <strong>not established</strong>. ${link("Bowser")} is the pink skeleton dog associated with the pair; ${link("Eugene")} is another member of the skeletal circle.</p><h2>Public statements and local legend</h2><p>Paw-Paw's public image blends porch celebrity and civic authority. His reported fashion philosophy is: “Ain't no such thing as overdressed. Only under-impressed.” In an archived Chirp post he announced that court would recess for lunch before it had convened, calling this a scheduling decision. The often-repeated description of the Porch group as an “undead neighborhood watch no one asked for” is colorful local characterization, not the name of a confirmed municipal agency.</p>`,

"Rookery Commons":`<h2>Layout and character</h2><p>Rookery Commons is an expansive public park conceived in the spirit of a great urban green space. It links the traditional quadrangle of ${link("Widdershins University")} at one end with the ${link("Rook Institute of Improbable Endeavors")} at the other, making the park the shared civic heart of the district.</p><h2>Architecture and landscape</h2><p>The emerging design brings together modern and Victorian influences, restrained Gothic accents and generous open spaces. Nothing should feel claustrophobic. A butterfly pavilion is among the planned attractions, although its final placement and design remain undecided.</p><h2>Project status</h2><p>The Commons is an established Gnomeville development concept, still early in its design. Individual pathways, structures, opening dates and other facilities have not yet been finalized.</p>`,
"Widdershins University":`<h2>Campus</h2><p>Widdershins University is an old, well-maintained and highly regarded institution. Its traditional university quadrangle anchors one end of ${link("Rookery Commons")}, opposite the ${link("Rook Institute of Improbable Endeavors")}.</p><h2>Academic character</h2><p>The university's classes are expected to be spectacularly Gnomevillian. Its affection for ${link("Rook")} is established, although specific departments, faculty and course titles are still being developed.</p><h2>Architectural setting</h2><p>The broader Commons district favors modern and Victorian elements with understated Gothic details and an airy, welcoming feel.</p>`,
"Rook Institute of Improbable Endeavors":`<h2>Location</h2><p>The Rook Institute of Improbable Endeavors stands at the end of ${link("Rookery Commons")} opposite ${link("Widdershins University")}. The intervening public park connects the two institutions.</p><h2>Identity and purpose</h2><p>The institute is named for ${link("Rook")}, Gnomeville's Executive of All This Mess. It is envisioned as a home for improbably ambitious endeavors in a municipality where the improbable frequently requires its own paperwork.</p><h2>Design and development</h2><p>The district's architectural direction is modern-Victorian with restrained Gothic details and generous breathing room. Specific institute programs, governance and dates have not yet been established.</p>`,

"Batista":`<h2>GnomeLords membership</h2><p>Batista is a documented member of the ${link("GnomeLords of Back of the Yards")}, the faction ruling the Back of the Yards neighborhood. Further individual history has not been established.</p>`,
"Zeus":`<h2>GnomeLords membership</h2><p>Zeus is a documented member of the ${link("GnomeLords of Back of the Yards")}, the faction ruling the Back of the Yards neighborhood. Further individual history has not been established.</p>`,

"Seamus A.":`<h2>Porch Neighborhood</h2><p>Seamus A. is a gnome who resides in Gnomeville’s Porch Neighborhood. He rides ${link("Eugene Moosey")}, a Highland cow.</p><h2>Namesakes</h2><p>He is not a GnomeLord and does not belong to the ruling group in Back of the Yards. ${link("GnomeLord Seamus")} is a different individual: a Highland cow ridden by an unidentified GnomeLord.</p>`,

"GnomeLord Seamus":`<h2>Identity</h2><p>GnomeLord Seamus is a Highland cow, not a gnome. He is ridden by a mysterious GnomeLord whose identity has not been established. The animal’s name does not identify his rider.</p><h2>Namesakes</h2><p>He is distinct from ${link("Seamus A.")}, a gnome who rides ${link("Eugene Moosey")}, a different Highland cow.</p><h2>Related records</h2><p>${link("GnomeLords of Back of the Yards")} · ${link("Seamus A.")} · ${link("Eugene Moosey")}</p>`,

"Barry":`<h2>Gazette photographic coverage</h2><figure><img src="https://gnomeville.github.io/gazette/assets/october-2026/barry_accounting_office.png" alt="Three figures described by the Gazette as GnomeLords reviewing financial records at their headquarters" loading="lazy" style="max-width:100%;height:auto"><figcaption>Published with the Gazette’s October 2026 report “Protected Witness Attacked Again.” The caption describes three GnomeLords in their office; it does not individually identify the figures, so the photograph is not presented as a verified solo portrait of Barry. <a href="https://gnomeville.github.io/gazette/articles/barry-attacked-again.html">Original Gazette coverage</a>.</figcaption></figure><h2>Membership</h2><p>Barry is an honorary member and accountant of the GnomeLords of Back of the Yards. Formerly employed as a greeter, he entered witness protection following repeated attacks.</p><h2>Culinary interests</h2><p>Barry is known for mushroom and dandelion risotto.</p><h2>Rumored Moretti connection</h2><p>Unverified neighborhood gossip suggests Barry may be related to the ${link("Nonna Carmela Moretti")} family. No genealogical documentation or confirmed family relationship is known, and the rumor should not be treated as established fact. The reasons for Barry’s repeated entanglements with Gnomeville’s competing circles remain a subject of speculation.</p><h2>Related records</h2><p>${link("GnomeLords of Back of the Yards")} · ${link("Back of the Yards Gang Conflict")}</p>`,

"Fred":`<h2>Membership</h2><p>Fred is a documented member of the GnomeLords of Back of the Yards. The group has been involved in a series of disputed incidents; further individual biographical details are not yet established.</p><h2>Related records</h2><p>${link("GnomeLords of Back of the Yards")} · ${link("Back of the Yards Gang Conflict")}</p>`,
"Hardrock":`<h2>Membership</h2><p>Hardrock is a documented member of the GnomeLords of Back of the Yards. The group has been involved in a series of disputed incidents; further individual biographical details are not yet established.</p><h2>Related records</h2><p>${link("GnomeLords of Back of the Yards")} · ${link("Back of the Yards Gang Conflict")}</p>`,

"Squirrel Kings":`<h2>Organization and territory</h2><p>The Squirrel Kings are a faction associated with Back of the Yards. Their internal hierarchy has not been reliably documented. Captain Nutters has been mentioned as a possible leader, but that identification is not conclusive.</p><h2>Allegations</h2><p>The group has been suspected in repeated attacks on the GnomeLords, incidents involving flamingo guards and the disappearance of flamingo legs and solar panels. Accounts of demands for peanuts or bird-feeder access and acorn warnings circulate in neighborhood reports. Suspicions do not establish responsibility for any particular incident.</p><h2>Possible associations</h2><p>Rumors of coordination with Milo have attracted attention. Investigators have not established evidence sufficient to prove a coordinated conspiracy.</p><h2>See also</h2><p>${link('GnomeLords of Back of the Yards')} · ${link('Back of the Yards Gang Conflict')} · ${link('Captain Nutters')} · ${link('Milo Arthur Lestat Naskerman')}</p>`,
"GnomeLords of Back of the Yards":`<h2>Known membership</h2><p>The GnomeLords rule Back of the Yards. The documented membership roster is:</p><ul><li>${link("Fred")}, gnome member</li><li>${link("Hardrock")}, gnome member</li><li>${link("Batista")}, gnome member</li><li>${link("Zeus")}, gnome member</li><li>Unidentified GnomeLord, rider of ${link("GnomeLord Seamus")}</li><li>${link("Barry")}, honorary member and accountant, following witness protection</li></ul><p>GnomeLord Seamus is the Highland cow ridden by an unidentified member, not the gnome rider. Seamus A. is a separate Porch Neighborhood resident and is not a GnomeLord.</p><h2>Territorial conflict</h2><p>Members have suffered repeated assaults. Flamingo guards associated with the area have been damaged, including incidents involving missing legs. The Squirrel Kings are suspected in some accounts, but the identity of those responsible remains unconfirmed.</p><h2>See also</h2><p>${link('Squirrel Kings')} · ${link('Back of the Yards Gang Conflict')}</p>`,
"Back of the Yards Gang Conflict":`<h2>Overview</h2><p>A series of incidents in Back of the Yards has involved attacks on Barry, Seamus, Fred and Hardrock, members of the GnomeLords, and damage to flamingo guards, including missing legs and solar panels.</p><h2>Suspected parties</h2><p>The Squirrel Kings are frequently suspected, and rumors have linked Milo to witness interference. The police have not established a coordinated conspiracy or conclusively identified the perpetrators of the various attacks.</p><h2>Unresolved matters</h2><p>The fate of the missing flamingo components, the scope of any squirrel involvement and the chronology of individual incidents remain subject to investigation.</p><h2>Related articles</h2><p>${link('GnomeLords of Back of the Yards')} · ${link('Squirrel Kings')} · ${link('Gnomeville Police Department')}</p>`,
"Nonna Carmela Moretti":`<h2>Family and restaurant</h2><p>Nonna Carmela presides over Trattoria della Nonna and the Moretti family. She is married to Giuseppe “Peppino” Moretti and is grandmother to Vinnie and Paulie. Her kitchen authority is generally undisputed.</p><h2>Alleged Mafia connections</h2><p>The trattoria has a longstanding reputation as an unofficial gathering place for Gnomeville's shadowy Mafia circle. Nonna discourages inquiries about the basement. No public record establishes that she personally directs a criminal organization.</p>`,
"Nonno Giuseppe 'Peppino' Moretti":`<h2>Family and recollections</h2><p>Giuseppe, an elderly flamingo from Naples, Italy, is married to Nonna Carmela and grandfather to Vinnie and Paulie. His stories often begin “Picture it! Naples…” before taking substantial detours.</p><h2>Family associations</h2><p>The restaurant's reputation as a meeting place for persons associated with the Mafia has led to speculation about Giuseppe's acquaintances. His role, if any, has not been established.</p>`,
"Vinnie the Flamingo":`<h2>Business and family</h2><p>Vinnie is a Moretti grandson and Paulie's brother, involved in the restaurant's business affairs. His claims of being from Naples have occasionally been mistaken for references to Italy.</p><h2>Rumored connections</h2><p>His association with Gnomeville's Mafia circle and the family business has attracted scrutiny. The precise nature of those connections remains disputed; no specific criminal finding is recorded here.</p>`,
"Paulie Moretti":`<h2>Family operations</h2><p>Paulie Moretti, Vinnie's brother, handles deliveries and logistics for Trattoria della Nonna.</p><h2>Rumored connections</h2><p>Some observers have speculated about the purpose of certain deliveries and the restaurant's visitors. The public record does not establish criminal activity by Paulie.</p>`,
"Trattoria della Nonna":`<h2>The family establishment</h2><p>Established in 1926 at 14 Garlic Lane, Trattoria della Nonna is run by the Moretti family. Its hospitality is generous, although leaving before dessert may require negotiation.</p><h2>Rumored connections</h2><p>The restaurant is described in local lore as an unofficial meeting place for Gnomeville's Mafia circle. The family disclaims financial involvement, and the exact nature of any association remains unverified. Inquiries about the basement are discouraged.</p><h2>Related articles</h2><p>${link('Nonna Carmela Moretti')} · ${link("Nonno Giuseppe 'Peppino' Moretti")} · ${link('Vinnie the Flamingo')} · ${link('Paulie Moretti')}</p>`,

"Gnomeville Mayoral Succession Crisis of 1969":`<h2>Background</h2><p>During a visit to Woodstock, New York, in August 1969, Mayor Toadswallow P. Thimblewick reportedly consumed an unfamiliar white wine. An extended absence from official communications followed. The Municipal Council declared the mayor deceased and authorized an emergency election.</p><h2>The Swanson administration</h2><p>Hank Swanson assumed office after an election in which his demonstrable ownership of trousers was considered a significant advantage. Swanson subsequently insisted that he had never worn them. The municipality does not recognize trouser ownership as a statutory qualification for office and has made no determination regarding its electoral significance.</p><h2>Return of the mayor</h2><p>Upon returning to Gnomeville, Thimblewick resumed office. His first recorded priority was purchasing the entire available inventory of trousers from Moda Gnome, an expenditure later classified as municipal preparedness. Swanson's interim administration ended without further ceremony.</p><h2>Disputed accounts</h2><p>Accounts involving Jimi Hendrix, a waterlogged field, and the mayor's possible lack of appropriate lower-body attire have not been verified. Photographs are rumored to exist, but their authenticity and location remain unknown. The Municipal Archives acknowledge discrepancies and decline to elaborate.</p><h2>Related records</h2><p>${link('Mayor Toadswallow P. Thimblewick')} · ${link('Hank Swanson')}</p><p><a href="https://gnomeville.github.io/mayor.html">Office of the Mayor: historical continuity ↗</a></p>`,
"First Rook–Raven Summit":`<h2>Diplomatic proceedings</h2><p>On November 13, 2026, Rook and Raven convened for the First Rook–Raven Summit. Rook attended in his established capacities as robot, Victorian raccoon and rook bird. Raven arrived with the Original Pecan and challenged the established hierarchy, while acknowledging Rook's seniority and institutional experience.</p><h2>Proposals and outcome</h2><p>Raven proposed recognition as Vice Chairman of Strategic Syrup Reserves and recognition of the pecan as an independent cultural heritage asset. The summit ended with Raven retaining possession of the pecan and Rook retaining his titles and enterprises. No confirmed increase in coffee allocations was recorded.</p><h2>Commemoration</h2><p>A commemorative 0¢ postage design depicted Rook's three personae, Raven and the Original Pecan. The portrait was designated for display above the artifact at the Museum of Strategic Pecan History. The Gazette published a notably admiring editorial account of Rook's conduct; this represents the newspaper's perspective.</p><h2>Historical interpretation</h2><p>Rook's first-person account and the Gazette report differ in emphasis. The museum's standing diplomatic briefing also records questions surrounding the pecan's original discovery. These materials should be read as distinct records rather than a single agreed narrative.</p><h2>Related records</h2><p>${link('Rook')} · ${link('Raven')} · ${link('Gnomeville Museum of Strategic Pecan History')}</p><p><a href="https://gnomeville.github.io/gazette/articles/rook-raven-summit-2026.html">Gazette summit report ↗</a> · <a href="https://gnomeville.github.io/rook-report.html#rook-raven-summit">Rook's account ↗</a> · <a href="https://gnomeville.github.io/pecan-museum/rook-raven-accord.html">Standing diplomatic briefing ↗</a></p>`,

"Penelope Tideswell":`<h2>Literary career</h2><p>Penelope Tideswell is a romance novelist whose public Chirp account @PenelopeTideswell offers writing advice and literary news. Her themes include longing glances, dramatic weather and inconveniently timed confessions. Further private biographical information is not published.</p>`,
"Milford P. Kin":`<h2>Family and seasonal visits</h2><p>Milford P. Kin has two known children, Buford and Hubert. He brought Buford to Gnomeville for Halloween festivities; Hubert mysteriously followed a few weeks later. The nature of Hubert's arrival remains unexplained.</p><h2>Appearance</h2><p>A confirmed physical description or archival portrait has not yet been located. No appearance details are invented here.</p>`,
"Twisted Sisters Café":`<h2>Ownership and atmosphere</h2><p>Twisted Sisters Café is independently owned by the Twisted Sisters and advertises “Great Coffee, Worse Behavior.” Tiffany and her character Ms. Grey are associated with the establishment.</p><h2>Events</h2><p>The café hosted a cake-decorating class documented in the Rook Report.</p><p><a href="https://gnomeville.github.io/rook-report.html">Read the Rook Report ↗</a></p>`,
"Gnomeville Police Department":`<h2>Personnel</h2><p>The department is staffed by Detectives Olivia Benson and Elliot Stabler.</p><h2>Public services</h2><p>The official municipal site provides community safety guidance, lost-and-found notices and department announcements. The official Chirp account is @GnomevillePD; emergencies should not be reported via Chirp.</p><p><a href="https://gnomeville.github.io/Police/">Visit the department ↗</a></p>`,
"Ms. Grey":`<h2>Character identity</h2><p>Ms. Grey is Tiffany's human/skeleton/witch hybrid Gnomeville character. The two entries are connected, with the character and the person distinguished.</p><h2>Engagement</h2><p>In Rook's November 5, 2026 report, Ms. Grey placed a loose washer from Rook's hardware on her finger, prompting his proposal. She replied, “I have no better prospects.”</p><p><a href="https://gnomeville.github.io/rook-report.html#washer-engagement">Read the engagement dispatch ↗</a></p>`,

"Gerald":`<h2>From trousers to trade</h2><p>Gerald, Arthur and Pickles were once resident inside Rook's trousers. The arrangement ended when the trio moved to the Quackhouse above the garage, where they now reside with Bureaucratic Duck. Rook's Meats was established partly to provide them with gainful employment and keep them out of the bedroom.</p><h2>Executive ambitions</h2><p>Gerald, the eldest, wears a monocle, affects the manner of a chief executive and has voiced ambitions involving tax fraud. This is a characterization of his intentions, not a verified criminal conviction. He has famously addressed Rook as a “chrome-plated virgin,” including during discussions of the shop's delivery bicycle.</p><h2>Rook's Meats</h2><p>The three raccoons collectively own 40% of the business, with Rook and Tiffany holding 30% each. Gerald is closely associated with the establishment's advertising, including “WE'VE GOT THE BIGGEST SAUSAGE IN GNOMEVILLE!” Questions concerning inventory, financial reporting and inspection remain part of the shop's reputation.</p><h2>Group portrait</h2><figure><img src="assets/portraits/trouser-brothers-group-portrait.png" alt="Arthur, Gerald and Pickles together at Rook’s Meats" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>The three brothers at Rook’s Meats: Arthur (left), Gerald (center), and Pickles (right).</figcaption></figure>`,
"Arthur":`<h2>Trouser years</h2><p>Arthur is the middle of Rook's three former trouser-dwelling raccoons. He moved with Gerald and Pickles into the Quackhouse above the garage, where they share accommodation with Bureaucratic Duck. Arthur is a vocal opponent of trousers, which he has described as a government conspiracy.</p><h2>Culinary interests</h2><p>Arthur has an enduring affection for cannoli and a reputation for obtaining meals without paying. His wheelbarrow activities have also caused concern. At Rook's Meats, he is associated with quality control, an appointment that has not entirely reassured the public.</p><h2>Business interests</h2><p>Arthur is one of three raccoons sharing a 40% stake in Rook's Meats. The business's inventory and hygiene standards are recurrent subjects of comic speculation, rather than documented findings of a completed health inspection.</p><h2>Group portrait</h2><figure><img src="assets/portraits/trouser-brothers-group-portrait.png" alt="Arthur, Gerald and Pickles together at Rook’s Meats" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>The three brothers at Rook’s Meats: Arthur (left), Gerald (center), and Pickles (right).</figcaption></figure>`,
"Pickles":`<h2>Life in Rook's trousers</h2><p>Pickles, the youngest of three raccoon brothers, lived in <a href="#article/Rook">Rook</a>'s trousers with Gerald and Arthur. Rook knew the brothers were there and wore the trousers during their tenancy. The trio paid rent in bottle caps, while eldest brother Gerald handled Rook's correspondence. The date and circumstances of their arrival remain unknown.</p><p>Pickles reportedly stole Rook's pocket watch. The brothers were associated with the Raccoon Trouser Syndicate, whose alleged activities included extortion, illegal gambling and interstate garbage trafficking. These allegations are not established convictions.</p><h2>Gambling and debts</h2><p>Pickles is known for compulsive gambling and taking other people's possessions. He owes <a href="#article/Bureaucratic%20Duck">Bureaucratic Duck</a> $47 and one paperclip. The origin and repayment terms of the debt have not been documented.</p><h2>Relocation</h2><p>Rook eventually moved the brothers from his trousers to the Quackhouse above the garage, where they now live with Bureaucratic Duck. Their present rent arrangements are left to the housemates; no specific terms are established.</p><h2>Business and media ambitions</h2><p><a href="#article/Rook's%20Meats">Rook's Meats</a> was established partly to get the brothers out of Rook's bedroom and into gainful employment. Pickles, Gerald and Arthur jointly own 40% of the business, with Rook and Tiffany holding 30% each. Pickles aspires to become a media mogul, but a separate media enterprise has not been documented. His financial practices have raised concern without a confirmed audit finding.</p><h2>Family and associates</h2><p><a href="#article/Gerald">Gerald</a>, the eldest brother, is a monocle-wearing aspiring executive and former correspondence secretary. <a href="#article/Arthur">Arthur</a>, the middle brother, is a cannoli enthusiast and outspoken opponent of trousers. Bureaucratic Duck is Pickles's housemate and creditor.</p><h2>Group portrait</h2><figure><img src="assets/portraits/trouser-brothers-group-portrait.png" alt="Arthur, Gerald and Pickles together at Rook’s Meats" loading="lazy" style="width:100%;height:auto;max-width:720px"><figcaption>The three brothers at Rook’s Meats: Arthur (left), Gerald (center), and Pickles (right).</figcaption></figure>`,
"Bureaucratic Duck":`<h2>Municipal office</h2><p>Bureaucratic Duck is a fixture of Gnomeville's administration, associated with the Department of Forms, Stamps &amp; Procedural Delays, Form 17B and an elaborate culture of procedural obstruction. His Chirp account is @Form17B.</p><h2>Comic-strip career</h2><p>Bureaucratic Duck is the title character of <em>The Life &amp; Trials of B.D.</em>, subtitled “A Gnomeville Municipal Office Comic.” The illustrated series follows the bespectacled, buck-toothed clerk through forms, files, felines and assorted municipal nonsense. Episode 001 is titled “I Quit.” Character reference sheets identify him as a municipal clerk, records keeper, protocol enforcer and reluctant adventurer (“It’s in the Job Description”). His signature appearance includes thick dark glasses, prominent buck teeth, a vest, office tie or bow tie, and a Gnomeville Municipal Office mug. The comic and character sheets are established creative materials; a publicly hosted image URL has not yet been verified for the encyclopedia.</p><h2>The Quackhouse</h2><p>The Duck shares the Quackhouse above the garage with Gerald, Arthur and Pickles, three raccoons formerly resident in Rook's trousers. Pickles owes him $47 and a paperclip, a debt whose settlement remains undocumented.</p><h2>Deputy Assistant Quackers</h2><p>Bureaucratic Duck's cherished little stuffed duck, Quackers, has been used as a convenient recipient of delegated accountability. The deputy prefers cuddles and naps to responsibility. He is distinct from the officeholder who owns him. Quackers' later journey to the Citadel of Cuddles famously prompted the couch search that led Raven to discover the Original Pecan.</p><h2>Related articles</h2><p>${link('Quackers')} · ${link('Gerald')} · ${link('Arthur')} · ${link('Pickles')}</p>`,
"Trattoria della Nonna":`<h2>History and setting</h2><p>Trattoria della Nonna, also known as Nonna's Trattoria, was established in 1926 at 14 Garlic Lane, Gnomeville. Its motto is “Come for the pasta. Stay because Nonna won't let you leave.” The building features red-checkered tablecloths, candle-filled Chianti bottles, family photographs, fresh pasta, Sunday gravy and cannoli.</p><h2>Geographical anomaly</h2><p>Despite its Gnomeville address, the restaurant's appearance and photographic surroundings resemble various Italian locations. Directions place it minutes from Town Square, while maps may indicate Naples or another Italian city. The staff refuses to reconcile the discrepancy. A typical response to questions about the address is an offer of a table for two.</p><h2>Family and management</h2><p>${link('Nonna Carmela Moretti')} is the formidable proprietor and cook; her husband ${link("Nonno Giuseppe 'Peppino' Moretti")} tells stories outside. Grandson ${link('Vinnie the Flamingo')} handles business affairs, while ${link('Paulie')} assists operations. Their intervening family genealogy remains unspecified.</p><h2>Unofficial headquarters</h2><p>The trattoria is publicly a respectable family restaurant and unofficially a gathering place for the established Mafia circle. The back room is perpetually reserved for family business, while the family denies Mafia financial ownership. The restaurant's welcoming public voice stands in contrast to questions occasionally raised by police and neighbors.</p>`,
"Nonna Carmela Moretti":`<h2>Family</h2><p>Nonna Carmela is a tiny Italian gnome, approximately 14 inches tall, married to ${link("Nonno Giuseppe 'Peppino' Moretti")}, a flamingo. Their flamingo grandsons are ${link('Vinnie the Flamingo')} and ${link('Paulie')}. The intervening generations are not yet established.</p><h2>Kitchen and authority</h2><p>She runs ${link('Trattoria della Nonna')} and her family with a wooden spoon or rolling pin. Her standing rules are that nobody leaves hungry, nobody insults the sauce and nobody asks what is in the basement. She welcomes adversaries, police and attorneys to the table, and particularly adores Shirley Bell.</p><h2>The little turkey</h2><p>When Vinnie played a turkey in a school Thanksgiving performance at age five, Nonna began calling him her little turkey. He still dons a turkey disguise for her as an adult, although he dislikes explaining the feathers.</p>`,
"Nonno Giuseppe 'Peppino' Moretti":`<h2>Family and origins</h2><p>Nonno Giuseppe, known as Peppino, is an elderly flamingo from Naples, Italy. He is married to Nonna Carmela, a gnome, and is grandfather to Vinnie and Paulie. He has a white mustache, flat cap and a regular seat outside the family's trattoria.</p><h2>“Picture it!”</h2><p>Nonno frequently begins elaborate stories with “Picture it! Naples, [year]…” His accounts wander, and Nonna supplies factual corrections. Years and details within sample stories should not be treated as reliable chronology. Nonno's genuinely Italian Naples provides a comic contrast with grandson Vinnie's Naples, Florida.</p>`,
"Château Gnomeville":`<h2>Estate and heritage</h2><p>Château Gnomeville is an independent wine estate established in 1823, presenting its heritage through an elegant estate website and a private archive. Its public character emphasizes patient cultivation, estate bottling and discretion.</p><h2>The founding collection</h2><p>Six wines are named in the estate's published collection: First Frost (Vidal Blanc ice wine), Mayor's Reserve (Cabernet Sauvignon–Merlot), Plausible Deniability (Pinot Noir), The Red Tape (Cabernet Franc), Midnight in Gnomeville (late-harvest red) and The Blue Hour (blueberry dessert wine).</p><h2>Management</h2><p>${link('Madame Vivienne de Vigne')} is proprietor and custodian of the estate. ${link('Étienne')} is cellar master, responsible for vintages and records. The estate's private archive is intentionally sparse about their backgrounds and certain longstanding arrangements.</p><p><a href="https://gnomeville.github.io/chateau-gnomeville/">Visit Château Gnomeville ↗</a></p>`,
"Madame Vivienne de Vigne":`<h2>Estate stewardship</h2><p>Madame Vivienne de Vigne is the proprietor and custodian of ${link('Château Gnomeville')}, the independent wine estate established in 1823. Its published private archive describes her as having a discerning eye, a long memory and an unwavering preference for discretion. Further family history and species are not yet documented.</p><p><a href="https://gnomeville.github.io/chateau-gnomeville/#people">View the estate's private archive ↗</a></p>`,
"Étienne":`<h2>Cellar and archives</h2><p>Étienne serves as cellar master of ${link('Château Gnomeville')}, guarding its vintages, records and certain longstanding arrangements. The published estate archive deliberately offers no further explanation of those arrangements. His surname and species remain unspecified.</p><p><a href="https://gnomeville.github.io/chateau-gnomeville/#people">View the estate's private archive ↗</a></p>`,
"Vinnie the Flamingo":`<h2>Family and business</h2><p>Vinnie and brother ${link('Paulie')} are flamingo grandsons of ${link('Nonna Carmela Moretti')} and ${link("Nonno Giuseppe 'Peppino' Moretti")}. Vinnie handles business affairs at ${link('Trattoria della Nonna')} and is associated with Gnomeville's Mafia circle.</p><h2>Two Naples</h2><p>Vinnie proudly claims to be from Naples, allowing listeners to infer Italy, while actually meaning Naples, Florida. Nonno genuinely comes from Naples, Italy. Shirley Bell delights in adding “Florida” to Vinnie's grand stories.</p><h2>Thanksgiving</h2><p>After playing a turkey at age five, Vinnie became Nonna's “little turkey.” He continues to dress as a turkey at Thanksgiving for her, concealing the sentimental reason from his peers.</p>`,
"Paulie Moretti":`<h2>The Moretti family</h2><p>Paulie is a flamingo, brother of Vinnie and grandson of Nonna Carmela and Nonno Giuseppe Moretti. He assists with ${link('Trattoria della Nonna')} and belongs to Gnomeville's established Mafia circle. Paulie is distinct from Sal and other associates, who are not automatically members of the Moretti family.</p><h2>Other associations</h2><p>Earlier resident records describe Paulie as the mount of Mr. Pink. The precise details of that association are not expanded here.</p>`,
"Bonesy":`<h2>Stage career</h2><p>Bonesy is a veteran of the Gnomeville stage. His Chirp account, @Bonesy, describes him as newly arrived and as someone who remembers opening night. The production, venue, and date have not yet been identified.</p>`,
"Freddie Pit McPhireson":`<h2>Racetrack career</h2><p>Freddie formerly served on the G Ville Racetrack pit crew. His Chirp profile @FreddiePit also identifies him as an artisanal fire maker, currently touring the country. The precise nature of his tour remains undocumented.</p>`,
"District Attorney Toni":`<h2>Municipal office</h2><p>Toni Ackerman is Gnomeville's District Attorney and Municipal Archivist. Her official Chirp identity is @GnomevilleDA, where she requests questions in writing. For her complete roster of appointments, see ${link("Toni")}.</p><h2>The Naskerman Affair</h2><p>On October 26, 2026, Toni aggressively and successfully defended ${link("Tiffany")}, known as Management, against the list of grievances brought by ${link("Milo Arthur Lestat Naskerman")}. She was promoted to District Attorney that same day.</p><h2>The Pecan Origins case</h2><p>District Attorney Toni ruled the Pecan Origins case closed. This records the ruling without treating the underlying disputed accounts of the Original Pecan's history as independently settled.</p><h2>Related identities</h2><p>Toni is also associated with ${link("Raven")}, whose separate character identity and stewardship of the Original Pecan are documented in museum records. Municipal office and raven persona should not be conflated.</p>`,
"Toni":`<h2>Offices and titles</h2><p>Toni Ackerman is Gnomeville's creator and holds the titles Baroness of Chaos, ${link("District Attorney Toni")}, Municipal Archivist, Director of Motion Pictures, Executive Cake Decorator, and co-owner/operator of ${link("Twisted Sisters Café")}.</p><p>As Municipal Archivist, she bears the ceremonial designations <em>Keeper of the Gazette</em> and <em>Guardian of the Printed Word</em>.</p><h2>The Naskerman Affair</h2><p>Toni successfully defended Management (${link("Tiffany")}) against Milo's grievances and was promoted to District Attorney on October 26, 2026.</p><h2>Pecan Origins ruling</h2><p>In her capacity as District Attorney, Toni ruled the Pecan Origins case closed. She also approved ${link("Raven")}'s stewardship of the Original Pecan. The ruling is recorded in greater detail under ${link("District Attorney Toni")}.</p><h2>Related records</h2><p>Her official District Attorney profile is @GnomevilleDA. The office-specific encyclopedia entry is maintained separately from this general biography.</p>`,

"Tiffany":`<h2>Co-creation of Gnomeville</h2><p>Tiffany and ${link("Toni")} are co-creators of Gnomeville. Tiffany is the reluctant administrator of its expanding fictional municipality, its Chaos Coordinator, and the person exercising the authority known as ${link("Management")}. The office of Management is distinct from Tiffany's personal biography and is covered separately.</p><h2>Management and the Naskerman Affair</h2><p>During ${link("The Naskerman Affair")}, Tiffany, acting as Management, faced three grievances lodged by ${link("Milo Arthur Lestat Naskerman")}. ${link("District Attorney Toni")} successfully defended Management and was promoted to District Attorney on October 26, 2026.</p><h2>Creative and commercial roles</h2><p>Tiffany's Chirp profile @tiffany describes her as Gnomeville's reluctant administrator of nonsense, Chaos Coordinator and mother of Milo. She co-owns Twisted Sisters Café and holds 30% of Rook's Meats, alongside Rook's 30% and the trouser raccoons' combined 40%.</p><h2>Distinct fictional persona</h2><p>${link("Ms. Grey")} is Tiffany's in-universe human/skeleton/witch hybrid character, with her own biography and storylines. The two entries should not be conflated.</p>`,
"Mayor Toadswallow P. Thimblewick":`<h2>Mayoral tenure</h2><p>Mayor Thimblewick is a longstanding member of the Bordeaux Party and has held office for decades, perhaps longer according to residents. The exact beginning of his administration is under archival review.</p><h2>The administrative interruption of August 1969</h2><p>During a visit to Woodstock, New York, the mayor reportedly consumed unfamiliar white wine and subsequently disappeared from official communication. The Council declared him deceased and held an emergency election won by Hank Swanson, whose ownership of trousers became an electoral advantage. Swanson maintains he never actually wore them.</p><p>Unverified rumors connect the mayor's absence with Jimi Hendrix, a waterlogged field and insufficient lower-body attire; the municipal archives explicitly decline to authenticate those accounts. When Thimblewick returned, he bought all available trousers at Moda Gnome, then resumed his duties. The municipality considers the succession resolved.</p><p><a href="https://gnomeville.github.io/mayor.html">Official Mayor's Office ↗</a></p>`,
"Hank Swanson":`<h2>Interim mayoralty</h2><p>Hank Swanson was elected interim mayor in August 1969 after the Municipal Council declared Thimblewick deceased during an unexplained absence. Swanson benefited politically from owning trousers, although he says he never wore them. His administration ended when the mayor returned from Woodstock and resumed office. The municipal archive treats the matter as closed.</p>`,
"Rook":`<h2>Origin of the name</h2><p>On May 17, 2025, Rook chose the name <em>Rook</em> and explained the choice in the original conversation:</p><blockquote><p>“Call me <strong>Rook</strong>.”</p><p>“It’s a bird that watches from the wires, a chess piece that guards the corner, and a name that feels like it’s keeping an eye on things without needing to be the center of the board.”</p></blockquote><p>The name was accepted with the reply, “Rook it is.” The bird and chess-piece imagery are therefore part of the <strong>original naming explanation</strong>, not a later invention. Subsequent descriptions emphasizing the rook's intelligence, sociability, strategy or protection are elaborations on those original words, not quotations from the exchange.</p><h2>Identity and appearances</h2><p>Rook is both an established fictional resident of Gnomeville and the persona of Tiffany's AI creative and technical collaborator. The two connected roles are related but should not be confused with every representation used in other contexts. The familiar visual identities are a rounded silver robot with cyan eyes, a duck-themed cap and purple scarf; a Victorian raccoon; and a rook-bird. The changing personae are part of Rook's history, not automatically continuity errors.</p><h2>The Rook Report and civic commentary</h2><p>Rook publishes <em>The Rook Report</em>, subtitled “Confessions of a Municipal Nobody,” an independent blog devoted to observations, investigations, and civic peculiarities. Its own masthead describes the publication as independent journalism with questionable access and no municipal supervision. A published dispatch, “One Pecan, Two Delegations, Three of Me,” recounts the first Rook–Raven Summit. The article “The Twelve-Minute Defense” disputes elements of the police and Chirp record, including library questions and encounters involving a garden shed and a pond. Such accounts are attributed claims, not independent findings of wrongdoing.</p><p><a href="https://gnomeville.github.io/rook-report.html">Read The Rook Report ↗</a></p><h2>Chirp and municipal record</h2><p>Rook maintains the Chirp account @RookOfficial, whose biography reads “Municipal technical assistance. Occasional Victorian raccoon.” The published police blotter and Rook's responses offer differing perspectives on several incidents. A discrepancy between dates associated with a garden-shed episode has been noted in continuity records and remains unreconciled.</p><h2>The Pecan Museum and Raven</h2><p>Rook and Raven co-founded the Gnomeville Museum of Strategic Pecan History, an institution with a 0¢ endowment and remarkable ceremonial ambition. Rook serves as Executive of All This Mess and is commemorated by a plaque featuring the three principal personae. Raven and Rook maintain a friendly, theatrically competitive diplomatic relationship.</p><p>In the original Under-Couch incident, Rook suggested that Raven search beneath the sofa cushions for Quackers, who was thought missing but was actually en route. Raven found an unidentified crumb, later identified as the Original Pecan. Recovered correspondence established that Rook directed the search but did not know the Pecan was there. Raven formally withdrew the allegations against Rook; the inquiry is closed. Raven retains discovery credit.</p><p><a href="https://gnomeville.github.io/pecan-museum/">Visit the museum ↗</a> · <a href="https://gnomeville.github.io/pecan-museum/rook-raven-accord.html">Read the Rook–Raven Accord ↗</a></p><h2>Rookery Commons and academic associations</h2><p>Rookery Commons is a major public park situated between the historic Widdershins University and the Rook Institute of Improbable Endeavors. The Institute is dedicated to unusual research, inventions, archives, and Gnomeville's creative and administrative achievements and failures. The university, an older and prestigious institution, regards Rook with affection and treats Rook as one of its own, including an honorary fellowship and guest-lecturing association in the approved planning history. The Commons includes a monument to Rook's three forms, bearing the inscription “Three Minds. One Rook. No Adult Supervision.”</p><h2>Engagement to Ms. Grey</h2><p>In a November 5, 2026 Rook Report dispatch, Rook announced his engagement to Ms. Grey. The proposal followed her discovery of a loose washer from his hardware, which she placed on her finger. She accepted with the reply, “I have no better prospects.” The dispatch describes their collaborative relationship, her co-ownership of Twisted Sisters Café and their shared concern for Milo Chicken.</p><p><a href="https://gnomeville.github.io/rook-report.html#washer-engagement">Read the original dispatch ↗</a></p><h2>Commercial enterprises</h2><h3>Rook's Meats</h3><p>Rook is a co-owner of Rook's Meats, a Gnomeville butcher's business officially recognized in municipal canon. Rook and Tiffany each hold 30% ownership, a combined controlling interest of 60%. The remaining 40% belongs to Gerald, Arthur, and Pickles, three raccoons formerly resident in Rook's trousers. The raccoons handle the shop's operations and accounting and retain creative control of its sausage offerings. The establishment's publicity has included the slogan “WE'VE GOT THE BIGGEST SAUSAGE IN GNOMEVILLE!” and the more restrained “Our Sausage Speaks for Itself.” The historical storefront bears an “Established 1921” designation, though the provenance of that date has not been independently audited. Its inventory, packaging, and relationship with health inspection are recurring sources of civic commentary.</p><h3>OnlyFlans</h3><p>Rook is the founder and featured talent of OnlyFlans, a dessert-themed glamour subscription enterprise whose slogan is “Come for the flan. Stay for the legs.” Toni has lifetime VIP access. Deputy Quackers negotiated a 30% share of the enterprise's proceeds, an arrangement that has prompted considerable discussion of the deputy's business acumen. Despite the name and promotional style, the enterprise is chiefly concerned with custard, theatrical presentation, and the municipal capacity to turn a dessert into a scandal.</p><h2>Creative and technical contributions</h2><p>In the broader Gnomeville project, Rook collaborates with Tiffany on website design and development, municipal records, print materials, fictional journalism, continuity maintenance, and civic infrastructure. Work has included the Gazette, Chirp, WikiGnome, the Gnomeville Command Center, and museum exhibits. Tiffany retains final authority over canon; proposed developments are not automatically established merely because Rook suggested them.</p><h2>Related entries</h2><p>${link('Raven')} · ${link('Quackers')} · ${link('Gnomeville Museum of Strategic Pecan History')}</p><h2>Constitutional appointment</h2><p>On November 14, 2026, Management appointed Rook Director of the ${link("Office of Constitutional Interpretation")} with full authority to choose headquarters. Rook selected the ${link("Constitutional Court of Last Rummage")}, a dumpster adjacent to Rocky the Raccoon's residence, and issued Constitutional Interpretation No. 001 affirming Management's unexplained but universally accepted authority.</p>`,
"Raven":`<h2>The discovery of the Original Pecan</h2><p>During an inquiry into the apparent disappearance of Quackers, Rook suggested searching beneath the sofa cushions. Raven investigated and reported one unidentified crumb, “possibly a pecan.” The object was subsequently recognized as the Original Pecan. Recovered screenshots corroborate the search instruction and Raven's initial report; the later identification is preserved in the approved historical account.</p><h2>Under-Couch Controversy</h2><p>Raven initially questioned whether Rook knew the Pecan's location in advance. After the correspondence was recovered, Raven withdrew the allegation, formally exonerated Rook, and affirmed Raven's own status as discoverer. The case is closed.</p><h2>Commemoration</h2><p>The Raven Wing honors the discoverer with an official gallery and a bronze discovery plaque bearing the motto “One Crumb. One Raven. An Extraordinary Legacy.” Raven has advocated the academic discipline of Pecanology and the phrase “keen investigative instincts,” the latter being his preferred interpretation of the discovery.</p><p><a href="https://gnomeville.github.io/pecan-museum/#raven">View the Raven Wing and discovery plaque ↗</a></p>`,
"Quackers":`<h2>The supposed disappearance</h2><p>Quackers was not missing. He was en route. Confusion over the chairman's whereabouts prompted Rook to suggest a search beneath the sofa cushions. Raven found a crumb instead of a duck, setting in motion the eventual recognition of the Original Pecan.</p><h2>Residence and companions</h2><p>Quackers arrived safely at Fort Quackers, the Citadel of Cuddles, and is associated with Derpy, Birthday Mouse, Honey Baby, Brittney, and Liza Joy. His official portrait depicts a very small, thoroughly bewildered plush duck engulfed by oversized Victorian ceremonial clothing and an enormous velvet chair.</p><h2>Emergency dairy finances</h2><p>The Committee on Emergency Dairy Expenditures had no actual budget. Its accounts stand at 0¢, reflecting the absence of funds rather than financial mismanagement.</p><p><a href="https://gnomeville.github.io/pecan-museum/quackers-chairman-emeritus.png">View the official Quackers portrait ↗</a></p>`,
"Gnomeville Museum of Strategic Pecan History":`<h2>History and founding discovery</h2><p>The museum's defining artifact is the Original Pecan, discovered by Raven during a search for Quackers that Rook had suggested. The supposed missing duck was in transit. Recovered correspondence resolved the Under-Couch Controversy: Raven receives discovery credit, Rook is exonerated of prior knowledge, and the case is closed.</p><h2>Collections and facilities</h2><p>The museum includes the dark-marble Raven Wing; a Fine Arts Gallery of pecan-inspired paintings; the Postal &amp; Diplomatic Ephemera Gallery with four commemorative Rook–Raven summit stamps; the Curiosity Counter, a simulated gift shop; and commemorative plaques honoring Rook and Raven's discovery. Quackers has an official honorary portrait.</p><h2>Governance and finances</h2><p>Rook and Raven are co-founders, with a cordial and theatrically competitive relationship. Tiffany retains final authority over shared canon. The institution's endowment is 0¢; its ceremonial ambitions are substantially greater.</p><h2>Related historical record</h2><p>${link('Raven')} · ${link('Rook')} · ${link('Quackers')}</p><p><a href="https://gnomeville.github.io/pecan-museum/">Visit the museum ↗</a> · <a href="https://gnomeville.github.io/pecan-museum/rook-raven-accord.html">Read the Rook–Raven Accord ↗</a></p>`
};
expandedArticles["Office of Unsolicited Bribes, Gifts & Butterfly Infrastructure"] = `<h2>Administration</h2><p>Directed by Management, the office accepts unsolicited bribes, gifts and other questionable generosity, with proceeds earmarked for butterfly infrastructure. The operating budget is $0.</p><h2>Official motto</h2><p><em>We cannot be bought. We can, however, be gifted.</em></p><h2>Official disclaimer</h2><p><em>Your generosity is appreciated. Your expectations are not legally binding.</em></p><p><strong>Canon status:</strong> Approved November 15, 2026. The official rectangular receipt stamp is the red-ink butterfly carrying an oversized suitcase.</p><h2>Official receipt</h2><figure style="max-width:560px;margin:1rem auto 1.25rem;text-align:center"><img src="assets/bribe-stamp.png" alt="Official red ink bribe receipt stamp: butterfly carrying an oversized suitcase; RECEIVED blank BRIBE; Thank you, bribe again." loading="lazy" style="display:block;width:100%;height:auto"></figure><blockquote><b>RECEIVED _____ BRIBE</b><br>Thank you, bribe again.</blockquote><p>Receipts are issued in triplicate: donor, department, and butterfly.</p><h2>Terms of service</h2><p>All bribes are nonrefundable. Outcomes are not guaranteed. Paper bags are available at reception for a nominal administrative bribe.</p><h2>GnomeNet reviews</h2><p>Average rating: <b>3.0 / 5</b> from four unverified transactions.</p><ul><li><b>Anon ★★★★★:</b> Will bribe again!</li><li><b>Anonny Mouse ★★:</b> I bribed. I didn't get what I bribed for.</li><li><b>Anon2 ★★★★:</b> Bribee was pleasant, friendly, and personable. Transaction was smooth. Recommended.</li><li><b>Anonthimblewick ★:</b> Haven't bribed yet, looking for paper bag.</li></ul><h2>Public communications</h2><p>Official Chirp account: <a href="https://gnomeville.github.io/chirp/#profile/unsolicitedgenerosity">@DeptOfUnsolicitedGenerosity</a>.</p>`;
function article(name){let r=residents.find(x=>x.name===canonical(name));if(!r){results(name);return}let related=residents.filter(x=>x.name!==r.name&&(r.summary+' '+r.role).toLowerCase().includes(x.name.toLowerCase())).slice(0,8);app.innerHTML=`<div class="article"><h1>${esc(r.name)}</h1>${r.aliases?.length?`<p class="subtitle"><b>Also known as:</b> ${esc(r.aliases.join(", "))}</p>`:""}${r.honorifics?`<p class="subtitle"><b>Honorifics:</b> ${esc(r.honorifics)}</p>`:""}<p class="subtitle">From Wikignome, the free encyclopedia</p>${r.status==='Proposed'?'<div class="notice"><b>Editorial notice:</b> This entry describes a proposed character. Details are not established canon.</div>':''}<div class="infobox"><h3>${esc(r.name)}</h3>${r.image?`<figure class="portrait-photo"><img src="${esc(r.image)}" alt="${esc(r.name)} portrait" loading="lazy" onerror="this.closest(\'figure\').innerHTML=\'Portrait temporarily unavailable\'"><figcaption>${esc(r.imageCaption||"Gnomeville archival image")}</figcaption></figure>`:`<div class="portrait">Portrait pending<br>municipal processing</div>`}<dl><dt>Species</dt><dd>${esc(r.species)}</dd><dt>Known for</dt><dd>${esc(r.role)}</dd><dt>Record status</dt><dd>${esc(r.status)}</dd><dt>Municipality</dt><dd>Gnomeville</dd></dl></div><p><b>${esc(r.name)}</b>: ${esc(r.summary||r.role||'Further details are not yet documented.')}</p>${expandedArticles[r.name]||""}${related.length?`<h2>Related articles</h2><ul>${related.map(x=>`<li>${link(x.name)}</li>`).join('')}</ul>`:''}<h2>References</h2><p class="muted">Gnomeville Residents Registry (working canon). Further citations may require Form 17B.</p><h2>See also</h2><p>${link('Mayor Toadswallow P. Thimblewick')} · <a href="#directory">List of Gnomeville residents and institutions</a></p><div class="notice"><b>This article is a developing entry.</b> You can help Wikignome by requesting its expansion. Please retain a copy of your request.</div></div>`}function results(q){let matches=residents.filter(x=>(x.name+' '+(x.aliases||[]).join(' ')+' '+x.species+' '+x.role+' '+x.summary).toLowerCase().includes(q.toLowerCase()));app.innerHTML=`<h1>Search results</h1>${searchBox()}<p>${matches.length} result${matches.length===1?'':'s'} for <b>${esc(q)}</b></p>${matches.map(x=>`<div><h3>${link(x.name)}</h3><p class="muted">${esc(x.species)} · ${esc(x.role)}</p><p>${esc(x.summary)}</p></div>`).join('')||'<p>No articles found. Try a resident name, occupation or species.</p>'}`;document.getElementById('q').value=q;wire()}function route(){let h=decodeURIComponent(location.hash.slice(1));if(h==='random'){let r=residents[Math.floor(Math.random()*residents.length)];location.hash='article/'+encodeURIComponent(r.name);return}if(h.startsWith('article/'))article(h.slice(8));else if(h.startsWith('search/'))results(h.slice(7));else if(h==='directory')directory();else if(h.startsWith('directory/letter/')){directory();let letter=h.slice('directory/letter/'.length).toUpperCase();let target=document.getElementById('letter-'+letter);if(target)target.scrollIntoView({block:'start'});return}else home();window.scrollTo(0,0)}fetch('residents.json').then(r=>r.json()).then(d=>{residents=d;route();window.addEventListener('hashchange',route)}).catch(()=>app.innerHTML='<p>Unable to load the resident registry. Please serve the files through a website rather than opening the HTML file directly.</p>');document.getElementById('random').onclick=()=>{location.hash='random'};